    const d = curData();
    if (!panel) return;
    const on = !!(d && CM.enabled);
    // banner
    let ban = $("apc-banner");
    const bsrc = on && d.profile && /^data:image\/(webp|jpeg|png);base64,/.test(d.profile.banner || "") ? d.profile.banner : "";
