      say("wait", `${esc(tr("Waiting for Arc…"))} <a href="${CONFIG.BLOCK_EXPLORER}/tx/${tx.hash}" target="_blank" rel="noopener">tx ↗</a>`);
      await tx.wait();
      say("ok", esc(tr("Locked. The badge is on your coin now.")));
