    const c = code();
    if (!c) return;
    paint(`<h2 id="tgl-h">${T("Link your wallet to ARCIA")}</h2><p class="tgl-p">${T("Checking the link…")}</p>`);
    let info = null;
    try { const r = await fetch(`/api/arcia-tg?linkinfo=${c}`, { cache: "no-store" }); info = r.ok ? await r.json() : null; } catch { info = null; }
